# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İDGAM-I MİSLEYN TANIMI VE GERÇEKLEŞME KURALI</text>\n  <rect x="30" y="50" width="640" height="75" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İdgam-ı Misleyn Nedir?</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#334155">Mahreçleri (çıkış yerleri) ve sıfatları birebir AYNI olan iki harften birincisi</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">SAKIN (cezimli) [ْ], ikincisi HAREKELİ [َ ِ ُ] olarak yan yana geldiğinde şeddeli gibi tek harf okunmasıdır.</text>\n  <rect x="30" y="138" width="305" height="98" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="162" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Sözlük ve Tecvit Kavramları</text>\n  <text x="48" y="185" font-size="11.5" fill="#334155">• <tspan font-weight="bold">İdgam:</tspan> Bir harfi diğer harfin içine katmak</text>\n  <text x="48" y="205" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Misleyn:</tspan> Birbirinin eşi/aynısı olan iki harf</text>\n  <text x="48" y="225" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Gunne:</tspan> Genizden gelen tınlamalı ses</text>\n  <rect x="365" y="138" width="305" height="98" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="162" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Birleşme Formülü</text>\n  <text x="517" y="190" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">بْ + بَ = بَّ   |   مْ + مَ = مَّ</text>\n  <text x="517" y="215" text-anchor="middle" font-size="11.5" fill="#334155">İki ayrı harf tek şeddeli harf gibi okunur!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İDGAM-I MİSLEYN ÇEŞİTLERİ: MEAL-GUNNE VE BİLA-GUNNE</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. İdgam-ı Misleyn Meal-Gunne (Gunneli)</text>\n  <text x="48" y="100" font-size="11.5" font-weight="bold" fill="#166534">Harfleri: م (Mim) ve ن (Nun)</text>\n  <text x="48" y="122" font-size="11" fill="#334155">• Sakin مْ harfinden sonra harekeli م gelirse:</text>\n  <text x="58" y="142" font-size="12" font-weight="bold" fill="#15803d">لَهُمْ مَا ← لَهُمَّا   |   عَلَيْهِمْ مُؤْصَدَةٌ</text>\n  <text x="48" y="168" font-size="11" fill="#334155">• Sakin نْ (veya tenvin) sonrası harekeli ن gelirse:</text>\n  <text x="58" y="188" font-size="12" font-weight="bold" fill="#15803d">مِنْ نِعْمَةٍ ← مِنِّعْمَةٍ   |   مِنْ نَاصِرِينَ</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Genizden ses getirilerek 1,5 elif tutulur!</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. İdgam-ı Misleyn Bila-Gunne (Gunnesiz)</text>\n  <text x="378" y="100" font-size="11.5" font-weight="bold" fill="#1e40af">Harfleri: م ve ن dışındaki diğer 26 harf</text>\n  <text x="378" y="124" font-size="11" fill="#334155">• بْ + ب : اِضْرِبْ بِعَصَاكَ ← اِضْرِبِّعَصَاكَ</text>\n  <text x="378" y="148" font-size="11" fill="#334155">• دْ + د : وَقَدْ دَخَلُوا ← وَقَدَّخَلُوا</text>\n  <text x="378" y="172" font-size="11" fill="#334155">• كْ + ك : يُدْرِكْكُمُ ← يُدْرِكُّمُ</text>\n  <text x="378" y="194" font-size="11" fill="#334155">• لْ + ل : قُلْ لَا ← قُلَّا   |   تْ + ت : رَبِحَتْ تِجَارَتُهُمْ</text>\n  <text x="515" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Geniz sesi yapılmadan doğrudan şeddelenir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN-I KERİM\'DEN İDGAM-I MİSLEYN UYGULAMA ÖRNEKLERİ</text>\n  <rect x="30" y="50" width="640" height="32" rx="6" fill="#1e293b"/>\n  <text x="140" y="71" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">Ayetten Örnek İfade</text>\n  <text x="350" y="71" text-anchor="middle" font-size="12" font-weight="bold" fill="#93c5fd">Birleşen Harfler</text>\n  <text x="550" y="71" text-anchor="middle" font-size="12" font-weight="bold" fill="#86efac">Tecvit Türü ve Okunuşu</text>\n  <rect x="30" y="86" width="640" height="34" fill="#f0fdf4"/>\n  <text x="140" y="108" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">أَطْعَمَهُمْ مِنْ جُوعٍ</text>\n  <text x="350" y="108" text-anchor="middle" font-size="11.5" fill="#1e293b">مْ + مِ (Sakin Mim + Mim)</text>\n  <text x="550" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Meal-Gunne (Gunneli idgam)</text>\n  <rect x="30" y="124" width="640" height="34" fill="#eff6ff"/>\n  <text x="140" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">إِذْ ذَهَبَ</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11.5" fill="#1e293b">ذْ + ذَ (Sakin Zel + Zel)</text>\n  <text x="550" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Bila-Gunne (Gunnesiz idgam)</text>\n  <rect x="30" y="162" width="640" height="34" fill="#f0fdf4"/>\n  <text x="140" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">مِنْ نِعْمَةٍ</text>\n  <text x="350" y="184" text-anchor="middle" font-size="11.5" fill="#1e293b">نْ + نِ (Sakin Nun + Nun)</text>\n  <text x="550" y="184" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Meal-Gunne (Gunneli idgam)</text>\n  <rect x="30" y="200" width="640" height="34" fill="#eff6ff"/>\n  <text x="140" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">فَمَا رَبِحَتْ تِجَارَتُهُمْ</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11.5" fill="#1e293b">تْ + تِ (Sakin Te + Te)</text>\n  <text x="550" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Bila-Gunne (Gunnesiz idgam)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
